scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'float'버튼을 클릭한다.
    //1. After running the sample, click the 'float' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 알림창에 'true' 값이 보여진다. (이전에는 'false' 값이 보여짐)
    //1. The 'true' value is displayed in the notification window. (Previously showing 'false' value)
    WebSquare.wUnit.addCommand("assert", "log", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'number'버튼을 클릭한다.
    //2. Click the 'number' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 알림창에 'true' 값이 보여진다.
    //2. The 'true' value is displayed in the notification window.
    WebSquare.wUnit.addCommand("assert", "log1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = ""; window.log1 = "";
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
